window.WBSC_QDICT = window.WBSC_QDICT || {};
WBSC_QDICT["es"] = {"m01-mkc":{"questions":[{"options":["Motivated (motivado) - mantener el entusiasmo en cada partido","Methodical (metódico) - seguir la misma rutina en cada partido","Managed (dirigido) - aceptar la corrección de los entrenadores sin cuestionarla","Mobile (móvil) - mantener el dinamismo y estar en posición"],"q":"En el acrónimo del árbitro de la Guía de Aprendizaje de Fundamentos («So, you want to be an umpire…»), ¿qué significa la letra M?"},{"options":["Estadístico - llevar el recuento de lanzamientos de ambos equipos","Entrenador - aconsejar a los jugadores cómo jugar su posición","Comunicador - hablar y escuchar de forma eficaz con los compañeros, los jugadores y los entrenadores","Enlace con patrocinadores - gestionar los acuerdos de patrocinio"],"q":"El Módulo 1 describe varias funciones que desempeña un árbitro competente. ¿Cuál de las siguientes es una de ellas?"},{"options":["60 minutos","45 minutos","30 minutos","90 minutos"],"q":"Según el Código Ético del Árbitro de la WBSC, ¿con cuánta antelación respecto a la hora programada del partido debe un árbitro cumplir su designación y presentarse en la sede?"},{"options":["Dar el beneficio de la duda al equipo local","Decidir sin tener en cuenta el marcador","Consultar a ambos entrenadores principales antes de las jugadas dudosas","Favorecer al equipo al que le quedan menos desafíos"],"q":"El Código Ético establece que los árbitros deben ser justos e imparciales en sus decisiones. ¿Qué dice concretamente que significa esto?"},{"options":["El marcador","El dugout","El círculo de espera","La base o la zona de la jugada"],"q":"La Teoría de los Cuatro Elementos Esenciales (FEET) del Módulo 3 enumera cuatro cosas que todo árbitro debe mantener a la vista. ¿Cuál de las siguientes es una de ellas?"}],"title":"Guía de Aprendizaje de Fundamentos","nextLabel":"Continúa con las presentaciones - De los Fundamentos al Apéndice 4"},"m01-pca":{"questions":[{"options":["Se declara ilegal al lanzador porque el equipo ha superado las tres conferencias defensivas permitidas por partido.","No ocurre nada: las conferencias defensivas son ilimitadas siempre que no sean para comprobar una lesión.","El entrenador principal es expulsado automáticamente por superar el límite de conferencias.","La conferencia simplemente no se contabiliza por ser la cuarta del partido."],"q":"Durante la entrada del Equipo A, el entrenador principal va al montículo para una cuarta conferencia defensiva en un único partido de 7 entradas para hablar de la estrategia de lanzamiento. Según la guía, ¿cuál es el resultado correcto?"},{"options":["Evitar mencionar la jugada para no avergonzar al árbitro que la falló.","Informar de la jugada fallada directamente al UIC sin hablarlo antes con el equipo arbitral.","Confrontar de inmediato al árbitro por el error en el campo antes de irse.","Hablar de la jugada con honestidad y respeto en la reunión posterior, centrarse en aprender en lugar de culpar y pedir permiso antes de cuestionar la decisión de otro árbitro."],"q":"Después del partido, un árbitro de base que falló una jugada ajustada en segunda quiere revisarla con el equipo arbitral. Según el enfoque de la guía para las reuniones posteriores, ¿cuál es la forma correcta de abordarlo?"},{"options":["Continuar el juego, ya que solo ver un relámpago, y no solo oír truenos, exige suspenderlo.","Pedir de inmediato «Time», suspender el juego y ordenar que todos los jugadores abandonen el campo.","Esperar y vigilar unos minutos más antes de decidir.","Continuar el juego, pero alejar del campo todo el equipamiento metálico."],"q":"Durante un partido se oyen truenos, pero no se ha visto ningún relámpago. Según el protocolo de seguridad ante tormentas de la guía, ¿qué debe hacer el árbitro?"},{"options":["Se concede la primera base al bateador, ya que cualquier bateador golpeado por un lanzamiento va a primera.","El árbitro debe preguntar al bateador si intentó esquivar el lanzamiento antes de dictaminar nada.","No se concede la primera base al bateador, porque no se puede conceder una base a un bateador golpeado por un lanzamiento que estaba en la zona de strike.","Se dictamina balk en el lanzamiento y todos los corredores avanzan una base."],"q":"Un bateador está muy dentro del cajón de bateo, encimado al plato, y es golpeado por un lanzamiento que estaba realmente dentro de la zona de strike. Según la guía, ¿cuál es el fallo correcto?"},{"options":["No hay problema: justo encima de la base se obtiene la visión más clara de una jugada forzada.","El árbitro debió usar la Teoría Dentro-Fuera, ya que esa solo se aplica a los fly.","El árbitro debió salir hacia el outfield en lugar de quedarse en el infield.","Desde justo encima de la base, la pelota, el fildeador, el corredor y el borde de entrada pueden parecer alineados, lo que dificulta juzgar el momento; el árbitro debe trabajar justo antes del borde de entrada y con un ligero ángulo."],"q":"En una jugada forzada en segunda base, el árbitro de base queda de pie justo encima de la base cuando llegan el tiro y el corredor. Según los principios de posicionamiento de la guía, ¿cuál es el problema y desde dónde debió trabajar el árbitro?"},{"options":["Quedarse fuera del diamante, más allá de las líneas de base.","Moverse directamente hacia el plato, sin importar dónde esté la pelota.","Moverse dentro del diamante, entre las líneas de base.","Permanecer en la zona de espera hasta que se fildee la pelota."],"q":"Se batea con fuerza una pelota hacia el hueco del outfield. Según la Teoría Dentro-Fuera, ¿hacia dónde debe moverse el árbitro de base para mantener los Cuatro Elementos Esenciales frente a él?"},{"options":["Volver hacia el infield para ayudar a cubrir la jugada en segunda base.","Quedarse fuera y dejar que terminen todas las jugadas, ya que regresar podría provocar que dos árbitros dictaminen la misma jugada.","Regresar de inmediato a su posición inicial sin importar las demás jugadas.","Pedir tiempo para reordenar las posiciones de los árbitros."],"q":"Un árbitro de base ha salido al outfield para dictaminar sobre un fly. Cuando el tiro regresa y se desarrolla una jugada en segunda base, que ya cubre otro árbitro, ¿qué debe hacer el árbitro que salió?"},{"options":["Expulsar al entrenador siguiendo el procedimiento de expulsión: esperar a que se detenga el juego, ser decidido y usar la señal de expulsión.","Ignorar los comentarios y continuar el partido para evitar que se agrave.","Dar una segunda advertencia antes de tomar cualquier otra medida.","Declarar de inmediato el partido perdido por incomparecencia."],"q":"Un entrenador principal ya ha recibido una advertencia por protestar una decisión de swing a medias, pero sigue protestando bolas y strikes y dirige un insulto personal al árbitro. Según la guía, ¿cuál es la respuesta adecuada?"},{"options":["Sí: la aplicación errónea de una regla es siempre un motivo válido de protesta, sin importar el momento.","No: aunque aplicar mal una regla es un motivo válido de protesta, no se dio aviso antes del siguiente lanzamiento como se exige.","Sí, pero solo si el entrenador la presenta por escrito en un plazo de 48 horas.","No: las disputas sobre las reglas de sustitución nunca pueden protestarse en ninguna circunstancia."],"q":"Un entrenador quiere presentar una protesta porque los árbitros aplicaron mal una regla de sustitución en la media entrada anterior, pero no lo plantea hasta que ya se ha lanzado una pelota en la media entrada siguiente. Según la guía, ¿es válida esta protesta?"},{"options":["Decir con claridad «Strike three... Out!», porque el bateador queda automáticamente fuera por regla en esta situación, y reforzar la decisión si el bateador echa a correr hacia primera.","Señalar de inmediato safe, ya que la pelota no fue atrapada.","No decir nada, ya que se espera que el bateador sepa que la pelota no fue atrapada.","Esperar a que el equipo a la defensiva apele antes de dictaminar nada."],"q":"Con un corredor en primera y un out, el bateador hace swing y falla un tercer strike que el receptor no atrapa limpiamente. Según la guía, ¿qué debe hacer el árbitro de home?"},{"options":["60 minutos antes","5 minutos antes","20 minutos antes","45 minutos antes"],"q":"¿Cuánto tiempo antes de la hora programada del partido dice la Guía de Aprendizaje de Fundamentos que los árbitros deben celebrar su reunión de compañeros?","why":"La guía establece la preparación personal a los 60 minutos, la reunión de compañeros a los 45, la inspección del campo a los 20 y la reunión en el plato a los 5 minutos antes del partido."},{"options":["Al menos 15 minutos antes del primer lanzamiento","En cuanto llegue el primer equipo","Al menos 60 minutos antes de la hora programada del partido","Al menos 3 horas antes del partido"],"q":"Según la Ética de Comportamiento de la Guía de Aprendizaje de Fundamentos, ¿con cuánta antelación debe presentarse un árbitro en el recinto?","why":"Los árbitros cumplen todas sus designaciones y se presentan en el recinto al menos 60 minutos antes de la hora programada del partido."},{"options":["60 minutos","15 minutos","10 minutos","30 minutos"],"q":"La guía dice que el juego no debe reanudarse tras una suspensión por rayos hasta que pase cuánto tiempo desde el último rayo visto o el último trueno oído.","why":"Ningún partido vale la vida de nadie: los jugadores abandonan el campo de inmediato y se refugian, y el juego no se reanuda hasta 30 minutos después del último rayo o trueno."},{"options":["El lanzador en 10 segundos y el bateador en 20 segundos","El lanzador en 25 segundos y el bateador en 5 segundos","El lanzador en 20 segundos y el bateador en 10 segundos","El lanzador en 30 segundos y el bateador en 15 segundos"],"q":"Para mantener el ritmo del juego, ¿en cuántos segundos debe lanzar el lanzador y con qué rapidez debe estar el bateador en la caja?","why":"La guía añade que un pie debe permanecer en la caja de bateo y que no se deben permitir conferencias largas."},{"options":["El partido se suspende y se completa al día siguiente","El partido termina con un marcador de 7-0 (o según las normas locales) a favor del equipo que no tiene la culpa","El partido termina con el marcador del momento de la negativa","El partido se repite desde el principio"],"q":"Un equipo se niega a seguir jugando cuando se le ordena. Según la guía, ¿cuál es el resultado de un forfeit?","why":"Los árbitros consultan al equipo arbitral y al UIC si lo hay, se aseguran de que se dieron y documentaron las advertencias debidas e informan con todos los detalles a la autoridad correspondiente."},{"options":["Una mala aplicación de una regla","Una decisión de bola o strike","Una decisión de quieto o out","Una decisión de fair o foul"],"q":"Según la guía, ¿cuál de las siguientes puede ser objeto de una protesta válida?","why":"Una protesta cuestiona la aplicación o interpretación de una regla, no el criterio del árbitro. Quieto/out, fair/foul, bola/strike, si hubo atrapada y si hubo interferencia u obstrucción son decisiones de criterio."},{"options":["48 horas","24 horas","Antes del siguiente lanzamiento","7 días"],"q":"¿En cuánto tiempo debe presentarse una protesta por escrito, salvo que las normas del torneo digan otra cosa?","why":"El aviso de la protesta en sí debe darse al árbitro de home antes del siguiente lanzamiento, antes de que los jugadores de campo abandonen el territorio fair o antes de que los árbitros abandonen el campo tras la última jugada del partido."},{"options":["Una expulsión dura una entrada; una retirada dura todo el partido","No hay ninguna diferencia","La expulsión se aplica solo a jugadores; la retirada, solo a entrenadores","Una persona expulsada debe abandonar el recinto por completo; una persona retirada por una infracción de las reglas puede quedarse en el dugout y seguir dirigiendo"],"q":"Según la guía, ¿cuál es la diferencia entre una expulsión y una retirada?","why":"Tras una expulsión el árbitro señala, dice en voz alta «[Nombre/Número] está expulsado», se aleja y deja que sus compañeros se encarguen de la retirada."},{"options":["Por cualquier motivo táctico","Solo si el entrenador contrario está de acuerdo","Solo por lesión o enfermedad","Solo por el clima"],"q":"En la reunión en el plato, el árbitro de home pregunta si hay cambios en las alineaciones. ¿Por qué motivos pueden cambiarse las alineaciones en ese momento?","why":"Una vez oficializadas las alineaciones, los cambios deben seguir las reglas de sustitución. En los Campeonatos Mundiales las alineaciones son oficiales cuando se presentan en el intercambio de alineaciones."},{"options":["Que el bate tiene el peso adecuado","Que el anillo se desliza libremente por el cuerpo del bate","Que el bate tiene una marca de certificación vigente","Que el agarre tiene la longitud adecuada"],"q":"¿Qué comprueba la prueba del anillo del bate?","why":"Si un bate es dudoso, el árbitro lo prueba con el anillo, consulta a sus compañeros, informa al entrenador y retira del juego los bates ilegales."}],"title":"Guía de Aprendizaje de Fundamentos","nextLabel":"Continúa con el Módulo 02 - Mecánica de campo de un árbitro"},"m02-mkc":{"questions":[{"options":["La pelota, los jugadores a la defensiva, los jugadores a la ofensiva y la base o la zona de la jugada","La pelota, los corredores, los entrenadores y el marcador","El lanzador, el receptor, el bateador y el infield","La pelota, los fildeadores, las líneas de foul y los dugouts"],"q":"Según la descripción general del Sistema de Un Árbitro, ¿cuáles son los «Cuatro Elementos Esenciales» que el árbitro debe intentar mantener siempre a la vista?"},{"options":["Permanecer detrás del plato hasta que se fildee la pelota","Salir rápidamente de detrás del plato hacia el infield para tener la mejor visión de la jugada","Pedir «Time» de inmediato para reordenar la defensa","Moverse directamente a primera base sin importar adónde se batee la pelota"],"q":"En el Sistema de Un Árbitro, ¿qué debe hacer el árbitro en cada bola bateada, antes de dictaminar nada?"},{"options":["«Umpire-in-Chief» o «UIC»","«Home» o «HU»","«Base Umpire» o «BU»","«Plate» o «PU»"],"q":"Según la sección de Convenciones, ¿cómo se denomina al árbitro de home en todo este manual?"},{"options":["Tres","Siete","Cinco","Diez"],"q":"Según la orientación sobre la posición inicial del árbitro de home, ¿cuántos lanzamientos de calentamiento se permiten a cada lanzador en la primera entrada y con cada lanzador nuevo?"},{"options":["Por el lado derecho, salvo que el bateador sea zurdo","Por el lado más cercano a donde se bateó la pelota","Directamente por el centro, entre el receptor y el bateador","Por el lado izquierdo, incluso con un bateador zurdo"],"q":"En cada bola bateada, ¿por qué lado indica el manual que debe salir el árbitro de home de detrás del receptor?"}],"title":"Fundamentos - Mecánica de campo de un árbitro","nextLabel":"Continúa con las presentaciones - De los Fundamentos al Apéndice 4"},"m02-pca":{"questions":[{"options":["Hacia el territorio de foul, en dirección a tercera base","Con decisión, hacia delante del plato en dirección a la zona del lanzador","Directamente por la línea de primera base, siguiendo al bateador-corredor","Quedarse detrás del receptor y dictaminar desde el plato"],"q":"No hay corredores en base y el bateador batea un rodado rutinario al shortstop. Según la mecánica de «Sin corredores en base», ¿hacia dónde debe moverse el árbitro de home para tener la mejor visión de la jugada?"},{"options":["Moverse hacia el territorio de foul, en dirección a tercera base","Moverse hacia delante del plato en dirección a la zona del lanzador, como cuando no hay corredores en base","Permanecer inmóvil detrás del receptor","Correr directamente a primera base"],"q":"Hay un corredor solo en tercera base y el bateador batea un rodado hacia el tercera base. Según la mecánica de «Corredor en tercera base», ¿qué movimiento debe hacer el árbitro de home?"},{"options":["Hacia delante del plato, en dirección a la zona del lanzador","Hacia la línea de foul del jardín derecho","Directamente detrás de segunda base","Hacia el territorio de foul, en dirección a tercera base"],"q":"Con las bases llenas, el bateador batea un fly hacia el jardín derecho corto. De acuerdo con la mecánica de «Bases llenas» (que sigue el mismo patrón que Corredor en tercera base), ¿hacia dónde debe moverse el árbitro?"},{"options":["Dictaminar de inmediato al ver el tiro y luego confirmar con una señal","Señalar primero y después cantar verbalmente","Parar… Esperar… Dictaminar y señalar","Moverse continuamente mientras se dictamina para mantener el ángulo sobre la jugada"],"q":"El árbitro de home se ha movido a la posición para una posible jugada en primera base sobre un rodado. ¿Qué secuencia prescribe el manual para dictaminar?"},{"options":["Solo si la pelota es fair o foul","La distancia de despegue del corredor","Si el fildeador es zurdo o diestro","Si hay atrapada o no"],"q":"Se batea un fly hacia el outfield sin corredores en base. Antes de moverse hacia la base donde se hará la jugada, ¿qué debe juzgar el árbitro?"},{"options":["Puede dictaminar y señalar «Time»","Seguir persiguiendo activamente la jugada por si un corredor intenta avanzar de nuevo","Regresar de inmediato a la zona del dugout","Convocar automáticamente una conferencia con los entrenadores"],"q":"La pelota ha regresado al infield tras una jugada en el outfield y el juego se ha detenido por completo. Según el manual, ¿qué debe hacer el árbitro de home?"},{"options":["El bateador-corredor que va hacia primera base","El corredor de primera base","El corredor de segunda base (el corredor adelantado)","El corredor que esté físicamente más cerca de la posición actual del árbitro"],"q":"Con corredores en primera y segunda base, se batea un fly hacia el jardín izquierdo que puede ser atrapado o no. De acuerdo con la instrucción del Sistema de Un Árbitro de dar prioridad en el posicionamiento, ¿qué corredor debe influir más en la posición del árbitro?"},{"options":["Permanecer fijo en la jugada de primera base hasta que termine por completo","Desplazarse hacia donde puede producirse la siguiente jugada, sobre todo porque es una posible jugada de tag","Pedir «Time» de inmediato en cuanto se suelta el tiro a primera","Moverse al outfield para preparar al siguiente bateador"],"q":"Se batea un rodado con un corredor en primera base. El tiro a primera para el bateador-corredor parece una jugada rutinaria y sin oposición, pero el corredor de primera puede intentar avanzar con el tiro. ¿Qué indica el manual que debe hacer el árbitro?"},{"options":["Mantenerse cerca de la línea para dictaminar fair/foul","Señalar «Out» de inmediato antes de que termine la jugada","Declarar out al corredor por correr fuera de la línea de base","Pedir ayuda al coach de tercera base"],"q":"Se batea con fuerza un rodado por la línea de tercera base con un corredor en tercera. Además de moverse hacia el territorio de foul en dirección a tercera base, ¿qué responsabilidad adicional asigna el manual al árbitro en esta situación?"},{"options":["Colocarse siempre exactamente a mitad de camino entre las dos bases implicadas en la jugada","Asegurarse de que la posición elegida no lo ponga en el camino de un jugador ni de una pelota lanzada","Mirar siempre al lanzador, sin importar dónde se desarrolle la jugada","Mantener siempre una distancia fija respecto a la base"],"q":"Mientras se mueve con decisión para ponerse en posición para una jugada que se está desarrollando, ¿qué principio de posicionamiento debe observar el árbitro, según la descripción general del Sistema de Un Árbitro?"},{"options":["En la placa del lanzador, mirando hacia home","Detrás del receptor en todo momento","A aproximadamente un tercio del camino de home hacia primera base en una media entrada y hacia tercera base en la otra, a unos 30 cm (12 pulgadas) de la línea, en territorio de foul","En segunda base, mirando hacia home"],"q":"En el Sistema de Un Árbitro, ¿dónde se coloca el árbitro de home entre entradas?","why":"El árbitro se coloca mirando al cuadro con las manos relajadas a los lados y la máscara bajo el brazo izquierdo."},{"options":["Siempre del lado de tercera base","Siempre del lado de primera base","Del lado del equipo que sale al campo","Del lado del equipo que sale del campo"],"q":"Entre entradas en el Sistema de Un Árbitro, ¿de qué lado se coloca el árbitro de home?","why":"El árbitro también apura a los equipos para que entren y salgan del campo."},{"options":["Cinco","Dos","Tres","Ocho"],"q":"¿Cuántos lanzamientos de calentamiento se permiten al inicio de cada entrada después de la primera?","why":"Se permiten cinco lanzamientos de calentamiento a cada lanzador en la primera entrada y con cada nuevo lanzador."},{"options":["Cuándo se ha lanzado el penúltimo lanzamiento de calentamiento","Cuándo se ha lanzado el primer lanzamiento de calentamiento","Nada; el receptor cuenta los lanzamientos","Cuál es el último lanzamiento, solo si se lo preguntan"],"q":"Durante los lanzamientos de calentamiento, ¿qué debe decirle el árbitro de home al receptor?","why":"Después de los lanzamientos de calentamiento, el árbitro limpia el plato y se coloca detrás del receptor."},{"options":["Dando un paso recto hacia atrás","Por la derecha, incluso con un bateador derecho","Por el lado del bateador","Por la izquierda, incluso con un bateador zurdo"],"q":"En cada batazo en el Sistema de Un Árbitro, ¿por dónde sale el árbitro de home de detrás del receptor?","why":"Si la pelota va cerca de la línea de foul, el árbitro se mueve a la línea y se coloca a horcajadas sobre ella para decidir si es fair o foul."},{"options":["Solo al corredor de tercera base","Al corredor de adelante","Al jugador de campo que tiene la pelota","Al bateador-corredor"],"q":"Con corredores en base, ¿a quién dice el Sistema de Un Árbitro que se debe dar prioridad en el posicionamiento del árbitro?","why":"En cada batazo el árbitro sale de detrás del plato hacia el cuadro para tener la mejor vista de la jugada que se desarrolla."},{"options":["Esperar a que el entrenador pregunte","Nunca se debe cantar una jugada sin salir de detrás del plato","Cantar las jugadas desde detrás del plato para no estorbar","Cantar la jugada antes de que llegue la pelota"],"q":"¿Qué dice el manual del Sistema de Un Árbitro sobre cantar una jugada?","why":"El árbitro único no tiene compañero que le ayude, así que debe moverse con determinación para obtener la mejor posición posible, detenerse y cantar la jugada."},{"options":["Para hacer señales a los entrenadores","Para contar el número de tiros","Para saber qué base limpiar","Por si la pelota sale del campo de juego"],"q":"¿Por qué debe saber el árbitro del Sistema de Un Árbitro dónde están los corredores cada vez que se lanza la pelota?","why":"El árbitro también debe echar un vistazo rápido a los corredores cuando tocan las bases, sobre todo al anotar en home."},{"options":["En la cabeza","Bajo el brazo derecho","Bajo el brazo izquierdo","En la bolsa de pelotas"],"q":"¿Dónde lleva la máscara el árbitro de home entre entradas en el Sistema de Un Árbitro?","why":"Durante la primera media entrada y cuando hay un cambio de lanzador, el árbitro puede ponerse la máscara para observar los lanzamientos de calentamiento."},{"options":["De todas las decisiones del partido, incluidos los lanzamientos ilegales, las bolas fair/foul, las infracciones de bateo y los quietos y outs","Solo de bolas y strikes","Solo de las decisiones en home","Solo de las bolas fair/foul"],"q":"En el Sistema de Un Árbitro, ¿de qué decisiones es responsable el árbitro de home?","why":"Es evidente que no se verá todo lo que ocurra, por lo que el árbitro único debe moverse con determinación por el cuadro y dentro de él para obtener la mejor posición."}],"title":"Fundamentos - Mecánica de campo de un árbitro","nextLabel":"Continúa con el Módulo 03 - Mecánica de campo de dos árbitros"},"m03-mkc":{"questions":[{"options":["La pelota","El marcador","Los jugadores a la ofensiva","Los jugadores a la defensiva"],"q":"Según el manual del Sistema de Dos Árbitros, ¿cuál de los siguientes NO es uno de los «Cuatro Elementos Esenciales» que un árbitro debe mantener sin obstrucciones a la vista?"},{"options":["Ambos árbitros conjuntamente","El árbitro de base","El árbitro que llegue primero","El árbitro de home"],"q":"Según el Principio de División del Sistema de Dos Árbitros, ¿qué árbitro es responsable de las decisiones en home y en tercera base en circunstancias normales?"},{"options":["Hacia el infield","Más adentro del outfield, hacia la pelota","A una posición sobre la línea de foul","Detrás del plato"],"q":"Según el Principio Infield/Outfield, ¿hacia dónde se mueve el árbitro de base cuando la pelota se batea al outfield?"},{"options":["El corredor adelantado es siempre el más rápido en base y necesita una supervisión más cercana","El árbitro de base siempre debe colocarse más cerca de segunda base, sin importar los corredores","El árbitro de base se coloca con el corredor adelantado porque se espera que el receptor intente una jugada de pickoff sobre ese corredor","El árbitro de home delega la cobertura del corredor adelantado para evitar la fatiga"],"q":"¿Cuál es la razón de ser del Principio del Corredor Adelantado en el Sistema de Dos Árbitros?"},{"options":["4-5 metros (15 pies) detrás de la línea de base, en territorio fair","Directamente detrás de la placa del lanzador, de cara al plato","3,5 metros (10-12 pies) detrás de primera base, sobre la línea de foul","5,5 metros (18 pies) detrás de primera base en territorio de foul, a 150 mm (6 pulgadas) de la línea"],"q":"Sin corredores en base, ¿cuál es la posición inicial del árbitro de base según el manual?"}],"title":"Fundamentos - Mecánica de campo de dos árbitros","nextLabel":"Continúa con las presentaciones - De los Fundamentos al Apéndice 4"},"m03-pca":{"questions":[{"options":["El árbitro de home, porque es una jugada forzada","El árbitro que esté físicamente más cerca de la base","El árbitro de base, que dictamina todas las jugadas del primer tiro en las jugadas de base","El árbitro de home, porque la bola bateada cayó en territorio fair"],"q":"Sin corredores en base, el bateador batea un rodado rutinario al shortstop, que tira a primera base. ¿Qué árbitro es responsable de la decisión en primera base?"},{"options":["Anticipar el doble play, moverse rápidamente hacia la base donde se hará la primera jugada y dictaminar todas las jugadas del primer tiro","Permanecer en la posición de espera en primera base hasta que termine el tiro","Moverse de inmediato a tercera base para cubrir el avance de R1","Ceder la cobertura de primera base al árbitro de home"],"q":"Con un corredor en primera base, el bateador batea un rodado que se convierte en un posible doble play. Según el manual, ¿qué debe hacer el árbitro de base?"},{"options":["El árbitro de home","El árbitro de base","Ambos árbitros conjuntamente","Ninguno: en los fly atrapados no se juzgan los tag-ups"],"q":"Con un corredor en primera base, el bateador batea un fly al outfield que es atrapado. ¿Qué árbitro es responsable de la decisión del tag-up en primera base?"},{"options":["El árbitro de home, según la regla general del Principio de División para tercera base","El árbitro situado más cerca del plato","El árbitro que tenga el ángulo más claro en ese momento","El árbitro de base"],"q":"Con corredores en primera y segunda base, R2 intenta robar tercera base en el lanzamiento. Según las excepciones al Principio de División, ¿qué árbitro tiene la decisión en tercera base?"},{"options":["R2, el corredor que estaba originalmente en segunda base","El bateador-corredor","R3, el corredor que estaba originalmente en tercera base","Ninguno: el árbitro de home lleva a todos los corredores hasta tercera base en los batazos al outfield"],"q":"Con corredores en segunda y tercera base, el bateador batea un fly profundo al outfield. Según el manual, ¿qué corredor lleva el árbitro de base hasta tercera base en esta jugada?"},{"options":["Como una jugada de tag que obliga al árbitro a moverse a 3,5 metros","Solo como un juicio de fair/foul","Como algo que requiere una apelación defensiva","Como una jugada forzada"],"q":"Con las bases llenas, el bateador batea un rodado a un jugador de cuadro. Según la nota del manual para esta situación, ¿cómo debe tratarse una jugada en cualquier base?"},{"options":["El árbitro de home, ya que las decisiones en tercera base siempre corresponden al árbitro de home según el Principio de División","El árbitro de base","El árbitro que haya iniciado la jugada más cerca de tercera base","El árbitro de home, porque el árbitro de base solo cubre las decisiones de primera y segunda base"],"q":"El bateador batea una pelota al outfield y, como bateador-corredor, avanza hasta tercera base. Según las excepciones al Principio de División, ¿quién dictamina sobre el bateador-corredor en tercera base?"},{"options":["5,5 metros (18 pies) detrás de primera base, en territorio de foul","Detrás y al lado del jugador de segunda base, inclinado hacia primera base","Detrás y al lado del shortstop, inclinado hacia el corredor de segunda base, con vista del lanzador, del corredor y de la zona del plato","En el césped del outfield, detrás de segunda base"],"q":"Con un corredor solo en segunda base y antes del lanzamiento, ¿dónde debe colocarse el árbitro de base?"},{"options":["Acercarse a unos 3,5 metros (10-12 pies) para ver y dictaminar la jugada","Permanecer a 5,5 metros (18 pies), ya que esa distancia se aplica a todas las decisiones","Moverse a 4-5 metros (15 pies) detrás de la línea de base","Retroceder más hacia el territorio de foul para obtener un ángulo más amplio"],"q":"El árbitro de base está colocado para una posible jugada en primera base y queda claro que el tiro requerirá un tag en lugar de un force. Según el manual, ¿qué ajuste debe hacer el árbitro de base?"},{"options":["El árbitro de base, ya que dictamina todas las jugadas, incluidos los tiros siguientes","Ambos árbitros deben dictaminarla simultáneamente","El árbitro que esté colocado en territorio fair","El árbitro de home, que es responsable de las jugadas sucesivas en tercera base o en home tras la primera jugada del infield"],"q":"Con corredores en primera y tercera base, se batea un rodado al infield. La defensa hace la primera jugada (un force en segunda base) y luego tira a home intentando sacar al corredor de tercera. ¿Qué árbitro es responsable de dictaminar esta segunda jugada posterior en home?"},{"options":["Segunda y tercera base","Primera y segunda base","Home y primera base","Tercera base y home"],"q":"Según el Principio de División del Sistema de Dos Árbitros, ¿qué bases se encarga normalmente el árbitro de base?","why":"El árbitro de home se encarga de todas las decisiones en home y en tercera base."},{"options":["El árbitro de home sale en cada fly","Los dos árbitros se quedan detrás de las bases","Cuando la pelota está en el cuadro interior, el árbitro de base se mueve o se queda en el jardín; cuando está en el jardín, se mueve a una posición en el cuadro","El árbitro de base siempre se queda en primera base"],"q":"¿Qué dice el Principio Infield/Outfield en el Sistema de Dos Árbitros?","why":"Así los árbitros no estorban la jugada y quedan en posición para ver la siguiente."},{"options":["Empezar siempre detrás del corredor de atrás","Empezar en la base donde no hay corredor","Empezar en una posición a la altura del corredor de adelante, porque se espera que el receptor juegue contra el corredor de adelante en un pickoff","Empezar junto al árbitro de home"],"q":"¿Qué pide el Principio del Corredor de Adelante al árbitro de base?","why":"El árbitro de base necesita estar en posición de cantar un pickoff del corredor de adelante."},{"options":["Un pie muy por delante del otro","Juntos, con el peso sobre los talones","Lo más separados posible","A una distancia cómoda, al menos el ancho de los hombros, relajado pero quieto"],"q":"Cuando el lanzador adopta la posición de set, ¿cómo debe colocar los pies el árbitro de base?","why":"Al soltar el lanzamiento, el árbitro afloja ligeramente las rodillas, con el peso ligeramente sobre la parte delantera de los pies y las manos recogidas cerca de la línea del cinturón."},{"options":["A unos 5,5 m (18 pies) detrás de primera base en territorio de foul, a 150 mm (6 pulgadas) de la línea","Junto al jugador de primera base, en territorio fair","A unos 10 m detrás de segunda base","A unos 3,5 m (12 pies) detrás de primera base en territorio fair"],"q":"Sin corredores en base, ¿dónde empieza el árbitro de base en el Sistema de Dos Árbitros?","why":"El árbitro de base mira hacia home con los hombros cuadrados al plato."},{"options":["A unos 10 m (33 pies)","A unos 3,5 m (10-12 pies)","A unos 5,5 m (18 pies)","Justo encima de la base"],"q":"¿A qué distancia aproximada se acerca el árbitro de base para ver y cantar una jugada de tag?","why":"En las jugadas forzadas el árbitro canta desde unos 5,5 m (18 pies). Durante una decisión es importante estar quieto y mantener a la vista los Cuatro Elementos Esenciales."},{"options":["Estar relajado","Mirar hacia home","Mantener una vista despejada de home","Colocarse por delante de cualquier jugador del cuadro antes de que el receptor reciba el lanzamiento o se batee la pelota"],"q":"¿Qué NO debe hacer el árbitro de base al colocarse antes del lanzamiento?","why":"El árbitro de base debe mantener una vista clara y sin obstáculos de home."},{"options":["Ir a segunda base","Seguir al bateador-corredor aproximadamente un tercio del camino hacia primera base, atento a una posible interferencia u obstrucción","Ir directamente a tercera base","Quedarse detrás del plato"],"q":"En un batazo al cuadro interior sin corredores en base, ¿qué hace el árbitro de home?","why":"Con un corredor solo en primera base, el árbitro de home sigue al corredor y luego se mueve a territorio de foul del lado de tercera base para una posible decisión sobre ese corredor en tercera."},{"options":["Justo al lado de la línea de tercera base, en territorio de foul, a aproximadamente un tercio del camino hacia tercera base","Justo al lado de la línea de primera base, a aproximadamente un tercio del camino hacia primera base","Detrás del receptor","En la placa del lanzador"],"q":"Entre entradas en el Sistema de Dos Árbitros, ¿dónde se coloca el árbitro de home?","why":"El árbitro de base se coloca justo al lado de la línea de primera base, en territorio de foul, a aproximadamente un tercio del camino hacia primera base."},{"options":["Solo el árbitro de home","El árbitro que esté más cerca de la placa del lanzador","Los dos árbitros comparten la responsabilidad","Solo el árbitro de base"],"q":"En el Sistema de Dos Árbitros, ¿quién es responsable de cantar los lanzamientos ilegales?","why":"El árbitro de home también es responsable de las bolas fair/foul y de las infracciones de bateo."}],"title":"Fundamentos - Mecánica de campo de dos árbitros","nextLabel":"Continúa con el Módulo 04 - Mecánica de campo de tres árbitros"},"m04-mkc":{"questions":[{"options":["La pelota, los jugadores a la defensiva, los jugadores a la ofensiva y la base o la zona de la jugada","La pelota, el lanzador, el receptor y la base","La pelota, el corredor, el entrenador y el marcador","La pelota, el fildeador, el dugout y la línea de foul"],"q":"Según los «Cuatro Elementos Esenciales» del manual del Sistema de Tres Árbitros, ¿cuáles son las cuatro cosas que un árbitro debe mantener sin obstrucciones a la vista para tener la jugada frente a él?"},{"options":["El árbitro de base que permanece","El árbitro de home","El árbitro que esté más cerca de tercera base","Ambos árbitros conjuntamente"],"q":"Según el Principio de División de los «Dos Principios Básicos de Cobertura» del Sistema de Tres Árbitros, cuando un árbitro de base sale a un fly, ¿qué árbitro dictamina todas las jugadas en home y en tercera base?"},{"options":["Correr hasta la malla de fondo para comprobar si hay interferencia","Indicar al receptor que se levante antes de cada lanzamiento","Dar un pequeño paso a la izquierda del árbitro de home para salir de detrás del receptor","Colocarse directamente detrás del receptor para obtener el mejor ángulo"],"q":"¿Qué significa «despejar al receptor» (clearing the catcher) para el árbitro de home, según el manual del Sistema de Tres Árbitros?"},{"options":["En cuanto el lanzador adopta la posición de set","Durante la reunión previa al partido","Solo después de que la pelota esté en juego","Cuando el lanzador inicia el lanzamiento"],"q":"En la Posición de Espera del Árbitro de Base descrita en este manual, ¿cuándo debe adoptar el árbitro la posición de «listo», flexionando ligeramente las rodillas y apoyando el peso en la parte delantera de los pies?"},{"options":["Moverse más allá de la línea de base para respaldar la jugada","Permanecer en la posición de espera en su base original","Rotar hacia el interior del diamante","Seguir la pelota hacia la cerca del outfield"],"q":"Según el Principio Infield/Outfield del Sistema de Tres Árbitros, ¿qué debe hacer un árbitro de base que NO sale a un fly una vez que la pelota está en el outfield?"}],"title":"Fundamentos - Mecánica de campo de tres árbitros","nextLabel":"Continúa con las presentaciones - De los Fundamentos al Apéndice 4"},"m04-pca":{"questions":[{"options":["El árbitro de home, siguiendo al corredor hacia segunda base","U1, que se queda en primera base y cubre también segunda","U3, que rota a segunda base alineado con el árbitro de home","U3 permanece en tercera base y no rota"],"q":"Sin corredores en base, se batea un rodado al infield que produce una posible jugada forzada en primera base. Si el bateador-corredor es declarado safe en primera y continúa hacia segunda base, ¿qué árbitro ha rotado a la posición para dictaminar esa jugada, según el manual del Sistema de Tres Árbitros?"},{"options":["El árbitro de home","U3","U1 regresa del outfield para llevar al corredor","La cobertura se reparte por igual entre el árbitro de home y U3"],"q":"Sin corredores en base, U1 sale a un fly al outfield. Si la pelota no es atrapada, ¿qué árbitro es responsable de llevar al bateador-corredor hasta segunda base y rodear hasta tercera?"},{"options":["Da un paso hacia segunda base para obtener un ángulo sobre el tiro","Se mueve a tercera base para cubrir un posible avance","Permanece en la posición de espera original, fuera de la línea de tercera base","Sale hacia el outfield para respaldar el tiro"],"q":"Con un corredor en primera base, se batea un rodado al infield que presenta un posible doble play. ¿Qué hace U3 en previsión del tiro a segunda base?"},{"options":["U3","El árbitro de home","U1 y U3 se reparten las decisiones","U1"],"q":"Con un corredor solo en segunda base, se batea un rodado al infield. ¿Qué árbitro es responsable de las decisiones tanto en primera como en segunda base en esta situación?"},{"options":["U1","U3, después de liberar tercera base","El árbitro de home, subiendo por la línea de primera base","Ningún árbitro: la jugada es de pelota muerta"],"q":"Con un corredor solo en tercera base, se batea un rodado al infield. Si U3 no puede liberar a R1 en tercera base (R1 no avanza a home), ¿qué árbitro puede tener que llevar al bateador-corredor a segunda base y dictaminar la jugada?"},{"options":["U3","El árbitro de home","U1, antes de salir hacia el outfield","Ningún árbitro vigila el tag-up en esta situación"],"q":"Con un corredor en tercera base, U1 sale a un fly. ¿Qué árbitro se mueve a la zona de espera entre home y tercera base para vigilar el tag-up de R1, preparándose a la vez para una posible decisión en home?"},{"options":["Se queda en territorio de foul detrás de tercera base","Rota de inmediato hasta tercera base","Se mueve hacia territorio fair aproximadamente un paso, en previsión de una jugada sobre R1","Sale al outfield para respaldar un posible tiro desviado"],"q":"Con corredores en primera y segunda base, se batea un rodado al infield que presenta un posible doble play. ¿Qué hace U3 en previsión de que el corredor adelantado (R1) avance desde segunda base?"},{"options":["Permanece en tercera base sin importar el avance de R1","Sigue a R1 hacia home","Rota de inmediato a primera base","Se mueve hacia territorio fair aproximadamente un paso, en previsión de una jugada sobre R2 que avanza desde segunda base"],"q":"Con corredores en segunda y tercera base, se batea un rodado al infield. Si R1 (el corredor de tercera) avanza hacia home, ¿qué hace U3, según el manual?"},{"options":["Primera base","Tercera base","El árbitro de home permanece en home","Segunda base, junto a U3"],"q":"Con un corredor en primera base, la pelota atraviesa el infield hacia el outfield y ningún árbitro sale. Mientras R1 avanza hacia segunda base, ¿hacia dónde rota el árbitro de home en preparación de una posible decisión?"},{"options":["Liberarse para cubrir home","Volver a salir más allá de la línea de base, en territorio fair","Permanecer en la línea de foul a la altura de la base","Rotar hacia el interior del diamante"],"q":"Con un corredor en segunda base, la pelota se batea a través del infield hacia el jardín derecho. Según la nota del manual, si existe la posibilidad de una jugada en tercera base con el tiro de regreso, ¿qué debe hacer U3?"},{"options":["El árbitro de base que queda se encarga de todo","El árbitro de home se encarga de todo","El árbitro de home se encarga de todas las decisiones en home y en tercera base, y el árbitro de base que queda, de todas las decisiones en primera y segunda base","El árbitro que salió conserva todas las decisiones"],"q":"Cuando un árbitro de base sale a un fly en el Sistema de Tres Árbitros, ¿cómo se divide el cuadro?","why":"Cuando el bateador-corredor llega a tercera base, el árbitro de base lo acompaña hasta allí."},{"options":["Mirar a sus compañeros y luego indicar y decir en voz alta «going»","Esperar a que el árbitro de home cante la pelota","Preguntar al entrenador","Salir corriendo sin hacer ninguna señal"],"q":"Antes de darse la vuelta para salir a un fly, ¿qué debe hacer el árbitro?","why":"El buen momento y el contacto visual entre árbitros son esenciales para una buena cobertura de los fly y para asegurarse de que sale el árbitro correcto."},{"options":["Hacia el anotador","Hacia home","Hacia la pelota, después de detenerse, decidir y comunicar","Hacia el dugout"],"q":"¿En qué dirección señalan los árbitros un out en un fly atrapado en el jardín?","why":"Los árbitros señalan que no hay atrapada si la pelota se juzga atrapada a ras de suelo; no hace falta señalar quieto si es evidente que no hubo atrapada."},{"options":["Quedarse en el jardín hasta que cese todo el juego, pero seguir observando las jugadas del cuadro para poder ayudar","Volver al cuadro de inmediato","Ir a segunda base","Quedarse y mirar solo el jardín"],"q":"Una vez que un árbitro ha salido al jardín, ¿qué debe hacer?","why":"Los demás árbitros vuelven al Sistema de Dos Árbitros."},{"options":["Siempre el árbitro de primera base","El árbitro más cercano al dugout","Siempre el árbitro de home","El árbitro que está en el jardín; si ningún árbitro de base salió al jardín, el árbitro de home"],"q":"¿Quién señala un jonrón en el Sistema de Tres Árbitros?","why":"Un árbitro de base que empieza en su línea de fair/foul y sale es responsable de las decisiones de atrapada/no atrapada, fair/foul y jonrón."},{"options":["El árbitro de segunda base, si lo hay","El árbitro de home","El entrenador","El jardinero más cercano"],"q":"Un árbitro de base no sale por error a un fly. ¿Quién canta la jugada?","why":"La única vez prevista en que el árbitro de home canta fair/foul y atrapada en un fly al jardín es cuando el árbitro que normalmente empieza en esa línea de fair/foul empieza en segunda base."},{"options":["Pedirle al receptor que se aparte","Moverse detrás del bateador","Caminar hasta la placa del lanzador","Dar un pequeño paso a la izquierda del árbitro de home para salir de detrás del receptor, creando espacio y abriendo la vista del campo"],"q":"¿Qué significa «despejar al receptor» en el Sistema de Tres Árbitros?","why":"Es la primera prioridad del árbitro de home tras cada lanzamiento o pelota bateada en la zona del plato, y debe ocurrir antes de que se desarrolle la jugada, no después."},{"options":["Detrás del receptor","En el extremo del lado del cuadro de la caja de bateo de los bateadores derechos","En el extremo del lado del cuadro de la caja de bateo de los bateadores zurdos, mirando hacia la red del fondo","En primera base"],"q":"En la reunión previa al partido en el Sistema de Tres Árbitros, ¿dónde se coloca U1?","why":"U3 se coloca en el extremo del lado del cuadro de la caja de bateo de los bateadores derechos. Inmediatamente después de la reunión, los árbitros de base pasan a las posiciones de entre entradas."},{"options":["U3","Quien esté más cerca del dugout","El árbitro de home","U1"],"q":"Tras el tercer out sin corredores en base, ¿quién limpia la placa del lanzador de camino a las líneas de base?","why":"Limpia la placa el árbitro de base más cercano a ella; si no hay corredores en base o ambos están a la misma distancia, se encarga U3."},{"options":["Solo la cuenta","El número de outs, la cuenta de bolas y strikes, la posición de los corredores y la posición de los jugadores de campo","Los nombres de los bateadores","El clima, el marcador y la hora"],"q":"Según el manual del Sistema de Tres Árbitros, ¿qué información deben conocer los árbitros antes de cada lanzamiento (Preparación Previa al Lanzamiento)?","why":"Conocer esto antes de cada lanzamiento ayuda al árbitro a anticipar las jugadas probables."}],"title":"Fundamentos - Mecánica de campo de tres árbitros","nextLabel":"Continúa con el Módulo 05 - Apéndice 4: Filosofías de posicionamiento de élite"},"m05-mkc":{"questions":[{"options":["La posición del árbitro, la velocidad del corredor, el ruido del público y el marcador","El lanzador, el receptor, el bateador y el plato","La pelota, el jugador defensivo, los jugadores ofensivos y la base o la zona de la jugada","La posición inicial, la posición de decisión, el punto focal y el borde de entrada"],"q":"Según los Conceptos Clave y el Glosario del Apéndice 4, ¿cuáles son los «Cuatro Elementos Esenciales» que un árbitro debe observar juntos para tomar una decisión precisa?"},{"options":["Una distorsión visual que se produce cuando el árbitro ve una jugada desde un mal ángulo que impide separar con claridad los elementos de la jugada y su momento","Una infracción que se produce cuando el pie de apoyo del lanzador cae fuera del carril de lanzamiento","El retraso entre que un árbitro ve una jugada y señala una decisión","Un error de mecánica causado por empezar demasiado lejos de la base"],"q":"En los Conceptos Clave y el Glosario del Apéndice 4, ¿cómo se define el «Error de Paralaje»?"},{"options":["Directamente sobre la línea de foul, a la altura de primera base","A unos 3-4 metros (10-12 pies) directamente detrás de home, alineado con el eje central del plato","Dentro del diamante, a mitad de camino entre home y la placa del lanzador","En el Ángulo Diagonal de Segunda Base, a 3-4 metros detrás de segunda base"],"q":"¿Dónde se encuentra por lo general la Posición del Punto del Plato (POP)?"},{"options":["Ver - Moverse - Reaccionar - Dictaminar","Posicionarse - Seguir - Juzgar - Señalar","Observar - Esperar - Confirmar - Anunciar","Parar - Ver - Decidir - Señalar"],"q":"¿Qué secuencia disciplinada identifica el Apéndice 4 como la técnica que usan los árbitros para evitar la anticipación y el sesgo cognitivo antes de tomar y comunicar una decisión?"},{"options":["El Apéndice 4 sustituye al Apéndice 5 para los árbitros por debajo del nivel de élite","El Apéndice 4 y el Apéndice 5 cubren el mismo contenido en formatos distintos","El Apéndice 4 aporta el porqué; el Apéndice 5 aportará el cómo","El Apéndice 4 es solo para entrenadores, mientras que el Apéndice 5 es solo para árbitros"],"q":"¿Cómo describe el Apéndice 4 su relación con el Apéndice 5?"}],"title":"Apéndice 4: Filosofías de posicionamiento de élite","nextLabel":"Continúa con las presentaciones - De los Fundamentos al Apéndice 4"},"m05-pca":{"questions":[{"options":["La señalización anticipada, porque el árbitro preparó la señal antes de que empezara la jugada","El sesgo de confirmación, porque fijarse en la acción del tag puede hacer que el cerebro confirme prematuramente un out y anule la relación real entre la pelota, el corredor y la base","El error de paralaje, porque el árbitro estaba colocado demasiado lejos de la jugada","Un incumplimiento de las responsabilidades primarias, porque el árbitro no rotó a la base correcta"],"q":"Durante una jugada de tag muy ajustada en tercera base, el árbitro ve claramente que el guante del fildeador toca la pierna del corredor, pero no sigue con claridad si la mano del corredor ya había llegado a la base. El árbitro declara out al corredor solo por el contacto del guante. ¿Qué principio del Apéndice 4 explica mejor el riesgo de este proceso de decisión?"},{"options":["No preocupa, porque la posición de slot del árbitro de home está alineada con todas las partes del campo","El árbitro de home debería dictaminar la jugada recordando la ubicación del lanzamiento y no la bola bateada","Solo preocupa para los juicios de jonrón, no para las líneas duras cerca de una base","El paralaje puede hacer que la pelota parezca fair o foul de forma errónea desde detrás del plato; la mecánica exige que el árbitro esté en la línea de foul para juzgar la jugada con precisión"],"q":"Una línea dura pasa cerca de la base de tercera. El árbitro de home, colocado detrás del receptor, es el único árbitro con vista de la jugada. Según la explicación del error de paralaje del Apéndice 4, ¿por qué preocupa esta posición y qué exige la mecánica correcta?"},{"options":["Permanecer fijo en el Ángulo Diagonal de Segunda Base sin importar cómo se desarrolle la jugada, ya que es la referencia inicial designada","Moverse de inmediato a la posición del Punto del Plato para obtener un mejor ángulo","Ajustar su posición a lo largo de la diagonal o salirse de ella según sea necesario, ya que la prioridad es siempre mantener una vista sin obstrucciones de los elementos clave","Pedir tiempo y reposicionarse solo después de que termine la jugada"],"q":"Un corredor que intenta evitar un tag de barrido en segunda base se desliza hacia la esquina trasera de la base, lejos de la posición del árbitro en el Ángulo Diagonal de Segunda Base. ¿Qué indica el Apéndice 4 que debe hacer el árbitro en esta situación?"},{"options":["El árbitro estaba en la posición equivocada o no esperó a que la jugada se desarrollara correctamente","El corredor cometió interferencia y debe ser declarado out automáticamente","El árbitro anticipó correctamente la jugada y debería mantenerse firme la próxima vez","Es una parte normal e inevitable de la mecánica de élite que no requiere ningún ajuste"],"q":"En una posible jugada de tag, un corredor corre directamente hacia el árbitro, obligándolo a moverse de repente para evitar una colisión. ¿Qué dice el Apéndice 4 que indica esta situación?"},{"options":["No decir nada, porque solo el árbitro de home tiene autoridad para dictaminar un lanzamiento ilegal","Esperar a la siguiente entrada para plantear el asunto al árbitro de home en privado","Si está seguro, dictaminar el lanzamiento ilegal, ya que la mecánica de la WBSC permite al árbitro cercano a segunda base controlar el pie de apoyo cuando está completamente fuera del carril de lanzamiento","Avisar discretamente al árbitro de home, pero nunca dictaminar la infracción directamente"],"q":"Durante un partido, el árbitro situado cerca de segunda base ve con claridad y sin dudas que el pie de apoyo del lanzador cayó completamente fuera del carril de lanzamiento, mientras que el ángulo del árbitro de home no le permite ver con claridad la infracción. Según el Apéndice 4, ¿qué debe hacer el árbitro cercano a segunda base?"},{"options":["Altera el momento de decisión y favorece las decisiones prematuras, porque el cerebro deja de procesar los elementos finales de la acción","No afecta a la precisión, ya que los árbitros con experiencia pueden hacer varias cosas a la vez con eficacia","Mejora el tiempo de reacción y es una técnica recomendada para las jugadas muy ajustadas","Solo afecta a las decisiones de bolas y strikes, no a las jugadas de tag"],"q":"Un árbitro empieza a formar mentalmente su señal de «out» mientras el fildeador aún está completando el intento de tag, antes de que la jugada haya terminado del todo. Según el Apéndice 4, ¿cuál es la consecuencia probable de este hábito?"},{"options":["U2 debe salir primero porque U2 tiene la posición inicial más central","Ambos árbitros deben salir a la vez para cubrir doblemente la jugada","Ningún árbitro debe salir; el árbitro de home debe cubrir todos los fly convergentes","U1 debe tener la primera oportunidad de salir, ya que U2 debe dar a U1 o a U3 la primera oportunidad y solo salir si ninguno lo hace"],"q":"En un sistema de cuatro árbitros, se batea un fly al hueco donde se superponen las zonas de cobertura de U1 y U2, y U1 también converge sobre la pelota. Según el Apéndice 4, ¿qué árbitro debe salir primero?"},{"options":["Los pies activos, que se usan únicamente para mantener el equilibrio mientras se está quieto","La técnica de la instantánea mental, en la que el árbitro toma una «fotografía mental» desde el ángulo inicial y otra desde el ángulo mejorado, y las combina en una imagen 3D más clara de la jugada","La corrección de paralaje, que elimina la necesidad de cambiar de posición","El principio del borde de entrada, que exige que el árbitro permanezca en todo momento a 90 grados de la trayectoria del corredor"],"q":"El ángulo inicial de un árbitro en una jugada de tag que se desarrolla es malo, pero el árbitro se mueve con decisión hacia un mejor ángulo cuando llega el tiro. ¿Qué técnica descrita en el Apéndice 4 refleja esto y cuál es su finalidad?"},{"options":["La posición más lejana con el ángulo limpio, porque en todos los casos los ángulos tienen prioridad sobre la distancia","La posición más cercana, porque la proximidad siempre produce el juicio más preciso","Ninguna; el árbitro debe pedir una revisión por video","La posición más cercana, porque la distancia tiene prioridad sobre el ángulo en la cobertura del outfield"],"q":"Un árbitro de base en un sistema de 3 o 4 árbitros debe decidir si sale a un fly. Una posición disponible está más cerca de la jugada, pero ofrece una línea de visión comprometida; otra está más lejos, pero ofrece un ángulo limpio y sin obstrucciones. ¿Qué elección refleja el principio del Apéndice 4 para las decisiones de cobertura del outfield?"},{"options":["Las Responsabilidades Primarias, porque el árbitro siempre debe rotar primero a otra base","El Posicionamiento y los Ajustes Dinámicos, porque no existe una posición «X marca el lugar»: las posiciones inicial y de observación nunca deben darse por la posición final de decisión","La Preparación Previa al Lanzamiento y la Cobertura del Outfield, porque el árbitro no anticipó la profundidad de los jardineros","El Error de Paralaje, porque el árbitro estaba alineado con el plano equivocado"],"q":"Un árbitro en formación trata su posición inicial de manual en segunda base como la posición desde la que debe hacerse cada decisión, incluso cuando un tiro y un tag llevan la jugada hacia el borde de entrada. ¿Qué principio clave del Apéndice 4 no refleja este enfoque?"},{"options":["Contar los lanzamientos de cada turno al bate","Memorizar la postura del bateador antes de cada lanzamiento","Tomar una foto con el teléfono después de la jugada","Tomar una fotografía mental de la jugada desde el ángulo inicial, moverse rápido a un mejor ángulo, tomar una segunda fotografía y combinarlas en una imagen 3D más clara"],"q":"¿Qué es la técnica de la «fotografía mental» que describe el Apéndice 4?","why":"El buen criterio nace de reunir la mayor cantidad posible de información visual; obtener el ángulo correcto suele importar más que la proximidad física."},{"options":["Señalar, ver la jugada, decidir, detenerse","Ver la jugada, señalar, decidir, procesar la jugada","Detenerse, ver la jugada, procesar la jugada, decidir, señalar","Decidir, detenerse, señalar, ver la jugada"],"q":"¿Qué secuencia da el Apéndice 4 para el buen momento de decisión en una jugada?","why":"Preparar la señal antes de que termine la jugada desvía la atención del cerebro de los elementos finales de la acción y fomenta cantar demasiado pronto."},{"options":["Que el árbitro se mueva demasiado pronto al borde de entrada","Que el árbitro pierda la cuenta","Que el cerebro «afirme» prematuramente un out porque ve el contacto del guante con el corredor, anulando la relación entre la pelota, el corredor y la base, por ejemplo que el corredor ya está tocando la base","Que el árbitro vea la pelota demasiado bien"],"q":"Según el Apéndice 4, ¿cuál es el riesgo de fijarse solo en la acción del tag?","why":"Un mal ángulo o el paralaje combinados con el sesgo de afirmación aumentan la probabilidad de una decisión incorrecta; cuando los ojos no están alineados con la jugada, el cerebro rellena la información que falta, a menudo de forma errónea."},{"options":["Solo cuando el árbitro de home se lo pide","Siempre que el pie toque el borde del carril","Solo en la primera entrada","Cuando el pie de avance cae totalmente fuera del carril de lanzamiento y la infracción es clara y evidente"],"q":"Según el Apéndice 4, ¿cuándo puede el árbitro cercano a segunda base cantar un lanzamiento ilegal por el pie de avance del lanzador?","why":"Solo el pie de avance debe caer dentro del carril de lanzamiento. El criterio para sancionar es que sea claro y evidente; el ajuste para verlo es temporal y no debe comprometer las responsabilidades principales."},{"options":["El árbitro de home desde detrás del receptor","Un árbitro situado en la línea de foul con una vista sin obstáculos del poste de foul","Cualquier árbitro dentro del cuadro","El árbitro cercano a segunda base"],"q":"Según el Apéndice 4, ¿quién puede juzgar con precisión si un fly profundo pasa por dentro o por fuera del poste de foul?","why":"Añadir distancia, o mirar desde dentro del cuadro, aumenta el error de paralaje; un árbitro cercano a segunda base está en un ángulo que distorsiona el juicio."},{"options":["La parte interior y la superior; la esquina exterior y la parte inferior son más difíciles de juzgar","La parte exterior y la inferior; la interior y la superior son más difíciles de juzgar","Solo el centro del plato","Todas las partes por igual"],"q":"Desde el slot, ¿qué partes de la zona de strike dice el Apéndice 4 que el árbitro de home ve con más claridad?","why":"Los ojos del árbitro de home están alineados con los planos interior y superior; para los lanzamientos exteriores y bajos, el punto de suelta del lanzador y el movimiento del guante del receptor aportan información adicional."},{"options":["Sobre la propia base","A aproximadamente 3-4 m (10-12 pies), dentro de la zona formada por el Ángulo Diagonal de Segunda Base y la extensión de la línea de tercera base","A aproximadamente 8-10 m (26-33 pies) directamente detrás de la base","A aproximadamente 1 m (3 pies), junto a la base"],"q":"Según el Apéndice 4, ¿a qué distancia detrás de segunda base está la posición inicial estándar de U2 o U3 en segunda base?","why":"Esta posición establece un punto de observación proactivo y permite al árbitro moverse con eficiencia alrededor de la base; empezar más lejos aumenta el arco de movimiento."},{"options":["Solo en los batazos que pasan la cerca","Solo cuando se lo pide el árbitro de home","En cualquier batazo que pueda ser atrapado por un jardinero de su zona de cobertura, que exija una decisión fair/foul en el jardín o que pueda ser jonrón","Solo en los batazos que son atrapados"],"q":"Según el Apéndice 4, ¿en qué batazos debe salir un árbitro de base en un sistema de 3 o 4 árbitros?","why":"En todos los casos, los ángulos tienen prioridad sobre la distancia."},{"options":["Se mueve hacia el interior para cubrir primera y segunda base, lo que reduce la necesidad de una rotación completa del equipo","Sale también","Se queda en segunda base","Rota a home"],"q":"En un sistema de Cuatro Árbitros, ¿qué hace U2 cuando U1 sale a un fly hacia la zona del jardín derecho?","why":"Que U1 salga en los batazos al jardín derecho mejora la cobertura de las bases más cercanas a home."},{"options":["U3 se encarga de todo el jardín","U1 se encarga de todo el jardín","El árbitro de home se encarga de todos los fly","Se divide por la mitad: U1 sale del jardín central a la línea de foul del jardín derecho y U3, del jardín central a la línea de foul del jardín izquierdo"],"q":"En un sistema de Tres Árbitros con U1 en primera base y U3 en tercera base, ¿cómo se divide el jardín para salir?","why":"Si un árbitro empieza en segunda base, la división cambia: el árbitro de home cubre los fly desde el jardinero izquierdo (o el derecho) hasta la línea de foul."}],"title":"Apéndice 4: Filosofías de posicionamiento de élite","nextLabel":"Continúa con el Módulo 06 - Apéndice 5: Mecánica de campo de élite"},"m06-mkc":{"questions":[{"options":["El lanzador, el receptor, el bateador y el árbitro de base","La pelota, el jugador defensivo, los jugadores ofensivos y la base o la zona de la jugada","La zona de strike, el despegue del corredor, el tag y el guante del fildeador","La posición inicial, la posición de observación, la posición de decisión y la base"],"q":"En la Teoría de los Cuatro Elementos Esenciales (FEET) del Apéndice 5a, ¿cuáles son los cuatro elementos que los árbitros deben observar juntos para dictaminar correctamente?"},{"options":["1-2 metros (3-6 pies)","6-12 metros (20-40 pies)","3-5 metros (9-15 pies)","2-4 metros (6-12 pies)"],"q":"Según el Apéndice 5a, ¿a qué distancia aproximada detrás de home se encuentra la posición del Punto del Plato (POP)?"},{"options":["A un árbitro que despeja al receptor para obtener una vista sin obstrucciones del campo","A un árbitro que se mueve al borde de entrada de una base para juzgar una jugada de tag","A un árbitro que rota en sentido contrario para cubrir una posición que no ocupa otro árbitro obligado a cubrir una jugada en otro lugar","A un árbitro que vuelve a su posición entre entradas cuando termina una jugada"],"q":"Según el Apéndice 5a, ¿a qué se refiere el «Backfilling»?"},{"options":["Permitir que dos árbitros dedicados al outfield cubran las responsabilidades de los fly, de modo que los demás árbitros puedan permanecer en el infield y cubrir las bases en todo momento","Sustituir al árbitro de home por dos árbitros adicionales de outfield","Eliminar la necesidad de cualquier rotación entre bases","Permitir que todos los árbitros actúen exclusivamente desde territorio de foul"],"q":"¿Qué finalidad asigna el Apéndice 5a a los Sistemas de Cinco y Seis Árbitros?"},{"options":["Apéndice 5a","Apéndice 5d","Apéndice 5c","Apéndice 5b"],"q":"El Apéndice 5 se divide en cuatro subsecciones (5a-5d). ¿Qué subsección abarca la mecánica del Sistema de Tres Árbitros?"}],"title":"Apéndice 5: Mecánica de campo de élite","nextLabel":"Continúa con las presentaciones - Apéndice 5, Parte A: Conceptos clave"},"m06-pca":{"questions":[{"options":["La pelota, el lanzador, el receptor y la base","El corredor, el fildeador, el entrenador y el marcador","La pelota, el jugador defensivo, los jugadores ofensivos y la base o la zona de la jugada","La pelota, el fildeador, el dugout y la línea de foul"],"q":"Según el Apéndice 5a, ¿qué cuatro cosas componen los Cuatro Elementos Esenciales (FEET) que el árbitro debe ver juntos en cada jugada?","why":"Los elementos deben observarse juntos, sobre todo el control de la pelota y los intentos de tag, porque la decisión correcta depende de ver cómo se combinan."},{"options":["Cuando el árbitro está demasiado lejos de la base para oír la jugada","Cuando el árbitro queda alineado en línea recta con el corredor, el fildeador, la pelota y la base o el punto del tag","Cuando el árbitro se mueve con pies activos durante la jugada","Cuando el árbitro está de pie en el borde de entrada de la base"],"q":"Según el Apéndice 5a, ¿cuándo se produce con más frecuencia el error de paralaje?","why":"Alinearse en línea recta reduce la percepción de profundidad y puede distorsionar la secuencia de los hechos. Los árbitros reducen el paralaje ajustando su posición para mantener el ángulo y la separación entre los elementos."},{"options":["Colocarse lo más atrás posible para ver todo el campo","Confiar en que el árbitro de base tome la decisión","Esperar a que la pelota se detenga antes de decidir","Colocarse en el plano de la decisión, por ejemplo sobre la línea de fair/foul"],"q":"Un árbitro quiere eliminar el error de paralaje en una decisión de fair/foul. ¿Qué dice el Apéndice 5a que debe hacer?","why":"Moverse al plano que forma la decisión convierte ese plano en una línea en la vista del árbitro, de modo que se puede juzgar directamente la posición de la pelota respecto a él."},{"options":["5,5 m (18 pies)","3,5 m (12 pies)","4,5 m (15 pies)","7 m (23 pies)"],"q":"Sin corredores en base, ¿a qué distancia aproximada de la base debe empezar un árbitro de base en 1B o 3B, según el Apéndice 5a?","why":"Sin corredores, la posición inicial es de 5,5 m (18 pies) en 1B y 3B, y de 4,5 m (15 pies) en 2B. Se reduce a unos 3,5 m (12 pies) cuando hay un corredor en la base del propio árbitro."},{"options":["Unos 3 m (10 pies) para una jugada forzada y 5 m (16 pies) para una de tag","Unos 5 m (16 pies) para una jugada forzada y 3 m (10 pies) para una de tag","Unos 5 m (16 pies) para ambas","Unos 3 m (10 pies) para ambas"],"q":"En una jugada, ¿qué distancia a la base indica el Apéndice 5a para una jugada forzada y para una jugada de tag?","why":"En una jugada de tag, el árbitro debe estar lo bastante cerca para ajustarse a izquierda o derecha y llegar al borde de entrada manteniendo todos los elementos frente a él."},{"options":["El ángulo","La distancia","El que esté más cerca de la base","Ninguno; el árbitro debe quedarse quieto"],"q":"Cuando el ángulo y la distancia no pueden ser ambos perfectos, ¿cuál tiene prioridad según el Apéndice 5a?","why":"Estar más cerca puede ayudar igualmente al árbitro a hacer movimientos controlados hacia un mejor ángulo, y el error de paralaje aumenta tanto con la distancia como con el ángulo."},{"options":["Es peligroso por los corredores que se deslizan","Le tapa la vista del dugout","Le impide usar la decisión verbal","Los ojos del árbitro quedan alineados verticalmente con la base, de modo que la pelota, el tag y el borde de entrada se reducen a una vista en línea recta sin percepción de profundidad"],"q":"¿Por qué dice el Apéndice 5a que un árbitro nunca debe colocarse directamente sobre una base al hacer una decisión?","why":"A velocidades de élite, la diferencia entre un tag en el borde de entrada y uno más allá puede ser de unos pocos centímetros. Una posición de decisión justo antes del borde de entrada mantiene los elementos visualmente separados."},{"options":["Fuera del diamante","Detrás de home","Dentro del diamante","En la línea de foul"],"q":"Según la Teoría Dentro/Fuera del Apéndice 5a, ¿dónde deben estar los árbitros de base que no han salido cuando la pelota está en el outfield?","why":"Cuando la pelota está en el outfield, los árbitros de base entran; cuando está en el infield, están fuera del diamante. Si algún árbitro sale, todos los demás deben entrar para cubrir las bases y hacer el backfill."},{"options":["Que PU comunique que se queda en HP para la jugada","Que el árbitro de base decida salir a un fly","Que un entrenador pida una conferencia","Que la pelota se devuelva al lanzador"],"q":"Según el Apéndice 5a, ¿qué desencadena una situación de backfill?","why":"Después de que PU comunica que se queda en HP, los árbitros de base se ajustan: el árbitro que no ha salido cubre 3B y U1 rota hacia el interior para cubrir 1B y 2B si es posible."},{"options":["Declarar safe al corredor","Declarar out al corredor, porque todavía está procesando que el tiro fue atrapado","Declarar interferencia","No ver la base"],"q":"En una jugada forzada en la que el corredor llega a la base y después el fildeador recibe el tiro, ¿qué error es más probable que cometa un árbitro que precipita la decisión, según el Apéndice 5a?","why":"Una ligera pausa en una jugada ajustada da al cerebro tiempo para procesar todos los datos en el orden correcto, en lugar de basar la decisión en lo último que se vio."},{"options":["En la extensión de la línea de tercera base, a unos 5 m detrás del plato","Justo al lado del receptor, del lado de 3B del plato","Dentro de la caja del receptor, alineado con el lanzamiento","A 2-4 m (6-12 pies) directamente detrás del plato, en el Punto del Plato (POP), hasta la extensión de la línea de primera base"],"q":"Según el Apéndice 5a, ¿dónde está la mejor Posición de Observación en home cuando PU no tiene que ir a la posición de espera, rotar a 3B ni cubrir el cuadro interior?","why":"Desde el POP el árbitro puede observar las jugadas en home y el resto del campo, y luego ajustarse a la posición de decisión que exija la jugada."},{"options":["El árbitro trota en el lugar entre lanzamientos para mantenerse en calor","El árbitro da pasos pequeños y rápidos solo mientras la pelota está en el aire","El árbitro mueve ambos pies al ajustar su posición, de modo que se mantiene equilibrado sobre la parte delantera de los pies y listo para moverse","El árbitro mantiene un pie fijo hasta que se canta la jugada"],"q":"¿Qué significa «pies activos» en el Apéndice 5a?","why":"Los árbitros nunca deben quedarse clavados en una posición. Mover ambos pies los mantiene estables y listos para moverse."},{"options":["Delante del jugador de segunda base, a la altura de la base","A unos 6 m (20 pies) directamente detrás de 2B","A unos 3,5 m (12 pies) detrás de 2B y a 1-2 m (3-6 pies) hacia el lado de 3B de 2B, si home y el bateador siguen bien a la vista","A unos 3,5 m (12 pies) detrás de 2B, del lado de 1B del Ángulo Diagonal de Segunda Base"],"q":"Con un corredor solo en 1B, ¿dónde puede usar el árbitro que trabaja en el Ángulo Diagonal de Segunda Base la Posición Inicial Alternativa?","why":"La Posición Inicial Alternativa da una posición de observación proactiva ante un posible robo, siempre que la vista de home y del bateador no tenga obstáculos."},{"options":["Porque pone la base entre el árbitro y la jugada y crea un error de paralaje al juzgar si el corredor está en contacto con la base","Porque deja al árbitro demasiado lejos del lanzador","Porque estorba el brazo de lanzamiento del jardinero central","Porque tapa la vista del receptor hacia home"],"q":"¿Por qué dice el Apéndice 5a que los árbitros no deben moverse más hacia la Extensión de la Línea de Primera Base (1BLE) que la Posición Inicial Alternativa en 2B?","why":"Alejarse del Ángulo Diagonal de Segunda Base hacia la 1BLE aumenta el error de paralaje y reduce la capacidad del árbitro para juzgar con precisión."},{"options":["En cada fly al jardín","Siempre que hay un corredor en 3B","En cada roletazo al cuadro interior","En un batazo fuerte o un fly de foul donde PU tiene una mejor posición para cantar la jugada desde detrás del plato o moviéndose con la trayectoria de la pelota"],"q":"Cuando PU no rota, ¿en qué situación NO hace su primer movimiento habitual de despejar al receptor hacia la izquierda?","why":"PU normalmente despeja primero al receptor hacia la izquierda. Las excepciones son un batazo fuerte o un fly de foul donde existe una mejor posición, y una bola pasada o un wild pitch cuando no tiene que rotar hacia 3B."},{"options":["El pronóstico del tiempo, la cantidad de público y el tiempo que queda de partido","La cuenta, el número de outs, el marcador, los corredores en base y su velocidad, y la profundidad y la fuerza de brazo de los jardineros","Solo la cuenta y el número de outs","La clasificación de los equipos y los resultados anteriores de cada bateador"],"q":"¿Qué información dice el Apéndice 5a que los árbitros deben repasar antes de cada lanzamiento (Preparación Previa al Lanzamiento)?","why":"La preparación mental evita que el árbitro quede desprevenido o mal ubicado en situaciones inusuales."},{"options":["Salir de inmediato en cada pelota bateada más allá del cuadro interior","Salir solo en las pelotas bateadas hacia su propio lado del campo","Esperar a que el árbitro de home indique quién sale","Mirar la trayectoria de la pelota, luego mirar a sus compañeros y comunicarse antes de decidir si sale"],"q":"Según el Apéndice 5a, ¿qué debe hacer un árbitro de base antes de decidir salir a un fly?","why":"Cada vez que el árbitro de 2B sale sin necesidad, puede comprometerse la cobertura en home, por lo que la decisión no debe precipitarse."},{"options":["Dejar la decisión al entrenador de primera base","Salir siempre, para juzgar si es fair o foul","No salir, para mantener la cobertura de las bases, sobre todo con varios corredores o con un corredor que va a home","Salir, pero volver antes de que la pelota caiga"],"q":"Según el Apéndice 5a, ¿qué debe hacer un árbitro ante un fly que realmente no tiene posibilidad de ser atrapado?","why":"Los árbitros deben conocer la profundidad, las posiciones iniciales y la capacidad de los jardineros. Deben salir en cualquier pelota que razonablemente pueda ser atrapada, pero no en las que no lo serán."},{"options":["Volver al cuadro interior y cantar la jugada, comunicándose con claridad con el equipo, o dar su opinión si se la piden","Correr directamente a home","Cantar la jugada sin avisar al equipo","Quedarse en el jardín sin decir nada"],"q":"Un árbitro que ha salido a un fly se vuelve y ve en el cuadro interior una base sin cubrir por una rotación omitida. Según el Apéndice 5a, ¿qué puede hacer?","why":"El árbitro que sale debe girarse y mirar hacia el cuadro interior. Decir «I'm here» y su nombre le indica al equipo que ha cubierto el lugar vacío."},{"options":["Que la pelota vuelva al círculo del lanzador","Que U1 pida tiempo en home","Una petición del entrenador de primera base","Que PU haga una señal desde la posición de espera"],"q":"Cuando U1 está en home al terminar una jugada, ¿qué libera a todos los árbitros para hacer la contrarrotación a sus nuevas posiciones para el siguiente lanzamiento?","why":"Los árbitros que llevan la jugada esperan a ser liberados para que el árbitro entrante tenga el control de la zona; si se van demasiado pronto, puede quedar una base sin ningún árbitro al mando."}],"title":"Apéndice 5a: Conceptos clave","nextLabel":"Continúa con la presentación - Apéndice 5b: Sistema de tres árbitros"},"m07-pca":{"questions":[{"options":["A mitad de camino de HP a 1B, fuera de la línea de fair/foul","A dos tercios del camino de HP a 3B","A un tercio del camino de HP a 3B","Detrás de los cajones de bateo, en el punto del plato"],"q":"En el Sistema de Tres Árbitros (Apéndice 5b), ¿dónde se coloca U1 entre entradas?","why":"Entre entradas, PU se coloca a un tercio del camino de HP a 3B, U1 a mitad de camino de HP a 1B y U3 a dos tercios del camino de HP a 3B, todos fuera de las líneas."},{"options":["A unos 3,5 m (12 pies) atrás, a dos tercios del camino de 1B a 2B","A unos 5,5 m (18 pies) detrás de 1B","A unos 3,5 m (12 pies) detrás de 1B, en territorio de foul","En el lado de 3B de 2B"],"q":"En el Sistema de Tres Árbitros, ¿dónde empieza U1 con un corredor solo en 1B?","why":"Sin corredores o con un corredor solo en 3B, la posición inicial es de unos 5,5 m (18 pies) detrás de 1B; con un corredor en 1B es más cercana para que el árbitro pueda mantenerse en territorio de foul con una vista clara."},{"options":["Para no estorbar al bateador en el círculo de espera","Para que el entrenador de tercera base pueda moverse libremente","Para estar listo para rotar a primera base","Para mantener una vista sin obstrucciones del lanzador, el corredor, el bateador y home, y que no le afecte el despegue del corredor cuando se suelta el lanzamiento"],"q":"¿Por qué coloca el Apéndice 5b a U3 a unos 3,5 m (12 pies) detrás de 3B, hasta a 2 m (6 pies) de la línea, cuando hay un corredor en 3B?","why":"La posición inicial se elige para que el árbitro pueda ver todo el lanzamiento y el despegue del corredor sin que el corredor le tape la vista."},{"options":["Hasta donde haga falta, incluso hacia el césped del infield","A unos 3 m (10 pies) de la base en territorio de foul, pero sin pasar de una línea de 45 grados que atraviesa 1B","Directamente al borde de entrada de 1B","Debe permanecer en la posición inicial"],"q":"En un pickoff (tiro de regreso) en 1B, ¿hasta dónde puede moverse U1, según el Apéndice 5b?","why":"Si U1 lee que la jugada será en el borde de entrada, puede entrar hacia territorio fair, manteniendo siempre los Cuatro Elementos Esenciales frente a él."},{"options":["El árbitro de base que permanece en el infield","El árbitro que salió","Nadie; no se vigila al corredor","PU"],"q":"En el Sistema de Tres Árbitros, cuando un árbitro de base sale a un fly, ¿quién asume la responsabilidad del tag-up en 3B?","why":"El árbitro de base que permanece en el infield se encarga de los tag-ups en 1B y 2B, y PU se encarga del tag-up en 3B."},{"options":["U1","U3","PU","El árbitro más cercano al corredor"],"q":"En el Sistema de Tres Árbitros, ¿quién es responsable de la decisión del despegue (lead-off) de un corredor en 2B?","why":"U1 es responsable de las decisiones de despegue de los corredores en 1B y 2B, y U3 de las de un corredor en 3B."},{"options":["U3","U1","PU","U1 y U3 la comparten por igual"],"q":"U1 está en 1B y U3 en 3B sin corredores en base. Se batea un fly al jardinero central (F8, en su posición normal) que se desplaza hacia el jardín derecho. ¿Quién es responsable de la decisión?","why":"U1 toma los fly a F8 que se desplazan hacia RF y foul; U3 toma los fly a F8 que se desplazan hacia LF y foul."},{"options":["U3","U1","PU","ULF"],"q":"U1 está en 1B, U3 está en 2B y hay un corredor en 1B. ¿Quién toma un fly al jardinero izquierdo (F7)?","why":"PU toma los fly a F7 y foul, U1 toma la zona del jardín derecho y foul, y U3 toma F8 y F7 desplazándose hacia CF. Que U1 tome los fly a F9 mantiene a U1 fuera de la trayectoria del corredor y deja a U3 entrar con más facilidad."},{"options":["Quedarse en su base","Entrar en el diamante, cubrir todas las decisiones en 1B o 2B y rotar a 3B por delante del bateador-corredor","Correr a home","Salir también al outfield"],"q":"Cuando U1 o U3 sale a un fly en el Sistema de Tres Árbitros, ¿qué debe hacer el árbitro de base que queda?","why":"Si la pelota es atrapada y el árbitro que queda puede llevar al último corredor a 3B y comunicarse con PU, debe hacerlo, lo que mantiene a PU en home para las jugadas importantes."},{"options":["Quedarse detrás del plato","Correr de inmediato a 3B","Salir hacia el outfield","Seguir al bateador-corredor aproximadamente un tercio del camino hacia 1B (más si hace falta), vigilar la interferencia y dictaminar fair/foul"],"q":"U1 está en 1B y U3 en 3B sin corredores en base y se batea un rodado al infield. Según el Apéndice 5b, ¿cuál es la tarea de PU?","why":"PU sigue al bateador-corredor por un posible tag, por interferencia del bateador-corredor o para ayudar en 1B, y rota a 3B si el bateador-corredor llega a 1B y avanza hacia 2B."},{"options":["Detrás de las cajas de bateo, en la punta del plato, con U1 y U3 a cada lado, delante de las cajas de bateo","En la línea de tercera base, con U1 y U3 detrás de PU","En la placa del lanzador, con los árbitros de base a su lado","Detrás de la caja del receptor, con los árbitros de base en sus bases"],"q":"¿Dónde se coloca PU en la reunión previa al partido en el plato en el Sistema de Tres Árbitros (Apéndice 5b)?","why":"Después de la reunión los árbitros van a sus posiciones iniciales; entre entradas todos los árbitros se colocan fuera de las líneas de fair/foul."},{"options":["A unos 5,5 m (18 pies) detrás de 3B, justo al lado de la línea en territorio de foul","A unos 3,5 m (12 pies) atrás, en el Ángulo Diagonal de Segunda Base","A unos 4,5 m (15 pies) detrás de 3B, justo al lado de la línea en territorio de foul","A unos 3,5 m (12 pies) detrás de 3B, hasta 2 m (6 pies) fuera de la línea"],"q":"En el Sistema de Tres Árbitros, con un corredor en 2B pero no en 3B, ¿dónde empieza U3?","why":"Sin corredores, la posición inicial está a unos 5,5 m (18 pies) detrás de 3B; con un corredor en 3B es más cercana, a unos 3,5 m (12 pies)."},{"options":["A unos 5,5 m (18 pies) detrás de 3B en territorio de foul","A unos 3,5 m (12 pies) atrás, en el Ángulo Diagonal de Segunda Base, o hasta la 3BLE del lado de 1B, con una vista sin obstáculos del bateador y de home","Del lado de 1B de la placa del lanzador","Al lado de PU, detrás de home"],"q":"En el Sistema de Tres Árbitros, con un corredor en 1B, ¿dónde puede empezar U3?","why":"Tanto la posición inicial estándar como la alternativa en el Ángulo Diagonal de Segunda Base ponen al árbitro cerca del ángulo, con un movimiento mínimo para una jugada de tag."},{"options":["PU","Nadie; no se vigila al corredor","U1","U3"],"q":"U3 empieza en 2B y U1 en 1B. Ningún árbitro de base sale a un fly. ¿Quién asume la responsabilidad del tag-up en 3B?","why":"Cuando ningún árbitro de base sale, cada uno se encarga del corredor de su propia base, y PU se encarga de 3B cuando U3 empieza en 2B o rota a 2B."},{"options":["Rotar de inmediato hacia el interior para cualquier decisión en 2B","Moverse a 1B","Quedarse en 3B hasta que el corredor se compromete a home y luego rotar hacia el interior para cualquier decisión en 2B","Rotar a home"],"q":"U1 está en 1B y U3 en 3B con un corredor en 3B. Se batea un roletazo al cuadro interior. ¿Qué hace U3?","why":"Si U3 se queda o se retrasa en 3B, U1 es responsable de las decisiones en 1B y 2B."},{"options":["Rotar directamente a home de inmediato","Quedarse en la posición inicial","Salir al jardín","Bajar por la línea de foul para posibles jugadas forzadas en 1B desde el jardín y rotar a la zona del POP solo si el bateador-corredor avanza de 2B a 3B, empujando a PU a 3B"],"q":"U1 está en 1B y U3 en 3B sin corredores. Se batea un roletazo al jardín. ¿Qué hace U1?","why":"U1 usa el movimiento dinámico para establecer una posición para cualquier decisión en 1B y solo rota a home cuando es posible una jugada en el plato."},{"options":["Rotar a home","Quedarse donde está y dejar que PU cubra 2B","Seguir hasta la cerca sin decir nada","Avisar a U1, con una señal y de viva voz, de que U3 tiene 2B y rotar de nuevo hacia el interior hasta 2B, mientras U1 acorta su rotación o hace un button hook hacia la línea de foul de 1B"],"q":"En el Sistema de Tres Árbitros, U3 empieza a salir a un fly que al principio creyó atrapable, pero luego juzga que no será atrapado. ¿Qué puede hacer U3?","why":"La corrección permite una mejor cobertura del bateador-corredor alrededor del cuadro."},{"options":["Retroceder hacia territorio de foul y girar sobre el hombro derecho","Entrar en el cuadro y luego girar sobre el hombro izquierdo, para poder cubrir varias bases","Correr en línea recta hasta home","La señal con la mano para una bola foul"],"q":"¿Qué significa «button hook» en el Apéndice 5?","why":"El button hook se usa siempre que U1 entra en el cuadro en un Sistema de Tres Árbitros, y le da a U1 la capacidad de adaptarse a una situación distinta."},{"options":["A unos 5,5 m (18 pies) atrás, en cualquier lugar del territorio de foul","Solo hasta el borde de entrada de la base","A unos 3 m (10 pies) de la base, pero sin pasar de una línea de 45 grados que atraviesa 3B","Debe quedarse en su posición inicial"],"q":"En un pickoff (tiro de regreso) en 3B en el Sistema de Tres Árbitros, ¿hasta dónde puede moverse U3 en territorio de foul?","why":"Observar la trayectoria de regreso del corredor ayuda al árbitro a llegar a la mejor posición para ver el tag o el borde de entrada."},{"options":["Rotar hacia el interior del cuadro para asumir la responsabilidad de 1B y 2B, moviéndose a un punto pasada la línea de la placa del lanzador a 2B","Rotar a home","Quedarse en 3B","Seguir a U1 al jardín"],"q":"Según el Mapa Mnemotécnico de Rotaciones del Sistema de Tres Árbitros, ¿qué debe hacer U3 siempre que U1 sale?","why":"El árbitro de base que queda se mueve hacia el interior y es responsable de todas las decisiones en 1B o 2B, y luego rota a 3B antes que el bateador-corredor."}],"title":"Apéndice 5b: Sistema de tres árbitros","nextLabel":"Continúa con la presentación - Apéndice 5c: Sistemas de cuatro, cinco y seis árbitros"},"m08-pca":{"questions":[{"options":["A un tercio del camino de HP a 1B","Detrás de 2B","Junto a PU","A dos tercios del camino de HP a 1B"],"q":"En el Sistema de Cuatro Árbitros (Apéndice 5c), ¿dónde se coloca U2 entre entradas?","why":"Entre entradas, PU se coloca a un tercio del camino de HP a 3B, U1 a un tercio del camino de HP a 1B, U2 a dos tercios del camino de HP a 1B y U3 a dos tercios del camino de HP a 3B."},{"options":["A unos 3,5 m (12 pies)","A unos 4,5 m (15 pies)","A unos 5,5 m (18 pies)","A unos 2 m (6 pies)"],"q":"En el Sistema de Cuatro Árbitros, ¿a qué distancia aproximada detrás de 2B empieza U2 cuando hay un corredor en cualquier base?","why":"Sin corredor, la posición inicial del Ángulo Diagonal de Segunda Base está a unos 4,5 m (15 pies) atrás; con un corredor en cualquier base, a unos 3,5 m (12 pies)."},{"options":["U1","PU","U2","U3"],"q":"En el Sistema de Cuatro Árbitros, ¿quién sale a un fly al jardín central?","why":"U1 sale a los fly al jardín derecho y a F8 que corre hacia la derecha; U3, al jardín izquierdo y a F8 que corre hacia la izquierda. U2 debe dar a U1 o a U3 la primera opción."},{"options":["U2","PU","U3","Nadie"],"q":"En el Sistema de Cuatro Árbitros, U1 sale a un fly. ¿Quién se encarga del tag-up en 1B?","why":"PU se encarga del tag-up en 1B porque PU tiene los Cuatro Elementos Esenciales frente a él en todo momento. U2 se encarga de 2B y U3 de 3B."},{"options":["U1","PU","U3","U2, desde el outfield"],"q":"En el Sistema de Cuatro Árbitros, U2 sale a un fly. ¿Quién se encarga del tag-up en 2B?","why":"U1 conserva 1B, U3 se encarga de 2B, incluido el tag-up, y PU se encarga del tag-up en 3B."},{"options":["U1 siempre hace un button hook hacia el interior","U1 usa el territorio de foul de 1B o sale, y nunca necesita hacer un button hook","U1 se queda en 1B durante toda la jugada","U1 cubre 3B en cada fly"],"q":"¿Qué afirmación sobre U1 en el Sistema de Cuatro Árbitros es correcta, según el Mapa Mnemotécnico de Rotaciones?","why":"U1 también se comunica con PU cuando llega a HP y empuja a PU hacia 3B, y se aparta de HP cuando PU indica una situación de backfill."},{"options":["Quedarse fuera para tener un ángulo agudo sobre el tiro desde el jardín izquierdo para cualquier decisión en 2B","Hacer de inmediato un button hook hacia el interior para cualquier decisión en 2B","Moverse a la zona POP para ayudar a PU","Rotar a 3B"],"q":"Sistema de Cuatro Árbitros. Se batea un rodado al jardín izquierdo y ningún árbitro de base sale. ¿Qué debe hacer U2?","why":"En un batazo a RF o CF, U2 hace un button hook hacia el interior para cualquier decisión en 2B; en un batazo a LF, el ángulo agudo sobre el tiro es mejor desde fuera."},{"options":["Detrás de la cerca del outfield","En la línea de foul a la altura de 2B","Junto a PU, detrás de home","Delante del jardinero, a mitad de camino entre el jardinero y el árbitro de base, hasta un metro fuera de la línea en territorio fair"],"q":"En los Sistemas de Cinco y Seis Árbitros (Apéndice 5d), ¿dónde toman ULF y URF su posición inicial preliminar?","why":"Si LF o RF juega cerca, el árbitro de outfield debe estar siempre delante del jardinero para juzgar con precisión las bolas atrapadas a ras de suelo."},{"options":["PU toma todas las bolas fair/foul hasta la posición inicial de U1 o U3, y ULF y URF toman todas las demás decisiones","ULF y URF toman todas las decisiones de fair/foul","El árbitro de base más cercano toma todas las decisiones","PU no toma ninguna"],"q":"¿Cómo se reparte la responsabilidad de fair/foul en los Sistemas de Cinco y Seis Árbitros, según el Apéndice 5d?","why":"Al seguir una pelota cerca del poste de foul, el árbitro de outfield se mantiene bien atrás sobre la línea de foul para tener la profundidad adecuada y juzgar la trayectoria sobre el poste o la cerca."},{"options":["Siempre la toma el árbitro más lejano a la pelota","PU decide desde el plato","La decisión la toma el árbitro de base","Ambos corren hacia territorio fair en paralelo a la trayectoria de la pelota hasta tener un ángulo, y quien toma la decisión lo indica con una mano en el pecho o verbalmente"],"q":"En un fly al outfield en los Sistemas de Cinco y Seis Árbitros, ¿cómo deciden los árbitros de outfield quién toma la decisión?","why":"ULF y URF son responsables de todas las decisiones más allá del árbitro de base y detrás de los jugadores de cuadro: fair/foul, atrapada o no, y el estado de una pelota que sale del campo de juego."},{"options":["A unos 3,5 m (12 pies) detrás de 3B, en territorio de foul","A unos 4,5 m (15 pies) detrás de 3B, justo al lado de la línea en territorio de foul","A unos 3,5 m (12 pies) atrás, en el Ángulo Diagonal de Segunda Base","A unos 5,5 m (18 pies) detrás de 3B, justo al lado de la línea en territorio de foul"],"q":"En el Sistema de Cuatro Árbitros, ¿dónde empieza U3 con un corredor en 2B?","why":"Sin corredores, U3 empieza a unos 5,5 m (18 pies) detrás de 3B; con un corredor en 3B está a unos 3,5 m (12 pies) en territorio de foul."},{"options":["U1","PU","U2","U3, desde el jardín"],"q":"U3 sale a un fly en el Sistema de Cuatro Árbitros. ¿Quién se encarga del tag-up en 2B?","why":"Cuando U3 sale, U1 se encarga del tag-up en 1B y U2 del tag-up en 2B. Cada árbitro tiene el tag-up de su base después de la rotación inicial."},{"options":["Salir también al jardín","Ignorar el tag-up","Pedir ayuda a U3 con el tag-up en 2B","Pedir a PU que se encargue del tag-up en 2B"],"q":"U1 sale a un batazo fuerte y plano que es atrapado en el jardín derecho. Puede que U2 no llegue al interior a tiempo para ver la atrapada y el tag-up del corredor en 2B. ¿Qué puede hacer U2?","why":"Cuando los árbitros rotan hacia el interior con la Teoría Interior/Exterior, puede que no vean a la vez el primer contacto con la pelota y el despegue del corredor, así que rotan rápido, miran por encima del hombro y piden ayuda."},{"options":["PU, para todos los corredores","U2, para los corredores en 1B y 2B, y U1 para los demás","U1, para los corredores de todas las bases","Cada árbitro, para el corredor de su propia base"],"q":"En el Sistema de Cuatro Árbitros, ¿quién es responsable de decidir si un corredor sale antes de tiempo?","why":"En el Sistema de Tres Árbitros U1 tiene las salidas anticipadas en 1B y 2B; en el Sistema de Cuatro Árbitros cada árbitro tiene la de su base."},{"options":["Unos 90 grados respecto al tiro y no más de 45 grados respecto al borde de entrada","Directamente sobre la base","Justo en línea con el tiro","Detrás del fildeador, a 180 grados del tiro"],"q":"¿Qué ángulo deben buscar U2 y U3 en las jugadas forzadas en el Sistema de Cuatro Árbitros?","why":"En las jugadas de tag usan el movimiento dinámico para mantener a la vista los Cuatro Elementos Esenciales en el borde de entrada o donde lo exija la jugada."},{"options":["Correr al jardín con la pelota","Seguir el batazo y acompañar al bateador-corredor un tercio del camino hacia 1B, más lejos si hace falta","Rotar de inmediato a 3B","Quedarse en home en su posición"],"q":"En el Sistema de Cuatro Árbitros sin corredores o con un corredor solo en 1B, ¿qué hace PU en un batazo al jardín?","why":"Con un corredor en 2B o 3B, PU usa en cambio la posición de espera y anticipa las jugadas en el plato."},{"options":["Siempre que U3 sale","Cuando no hay corredores y el batazo va al jardín izquierdo","Siempre que el batazo va al cuadro interior","Cuando hay un corredor en 3B y el batazo va al jardín derecho"],"q":"Según el Mapa Mnemotécnico de Rotaciones del Sistema de Cuatro Árbitros, ¿en qué situación puede quedarse afuera U2?","why":"U2 debe rotar hacia el interior del cuadro en todas las demás situaciones en que U1 o U3 salen, y cubrir 1B cuando U1 sale."},{"options":["Salir al jardín en cada fly","Quedarse en sus posiciones iniciales durante toda la jugada","Dejar todas las decisiones a los dos árbitros de jardín","Quedarse en el cuadro interior y rotar como en el Sistema de Tres Árbitros, mientras dos árbitros de jardín situados en las líneas de fair/foul juzgan los fly, las bolas atrapadas a ras de suelo y los jonrones"],"q":"En el Sistema de Cinco Árbitros (Apéndice 5d), ¿qué hacen PU y los dos árbitros de base?","why":"Esto deja a los demás árbitros libres para atender las jugadas en las bases."},{"options":["Al círculo del lanzador","Detrás de home, al lado de PU","Por la línea hasta donde están las posiciones iniciales de U3 y U1","Detrás de la cerca del jardín"],"q":"Entre entradas en los Sistemas de Cinco y Seis Árbitros, ¿adónde van ULF y URF?","why":"Los demás árbitros usan las mismas posiciones entre entradas que en el Sistema de Tres o de Cuatro Árbitros."},{"options":["Permiten que los árbitros de base se queden en el cuadro interior, de modo que todas las bases estén cubiertas en todo momento y cada decisión se tome desde una posición ventajosa","Hacen que los partidos sean más cortos","Eliminan la necesidad de que PU esté en home","Eliminan la necesidad de decidir si la bola es fair o foul"],"q":"Según el Apéndice 5, ¿por qué son útiles los Sistemas de Cinco y Seis Árbitros?","why":"Las jugadas cercanas a home afectan el resultado general del partido, por lo que importa tener cubiertos 3B y home; los sistemas son adecuados para finales y partidos de alto nivel."}],"title":"Apéndice 5c: Sistemas de cuatro, cinco y seis árbitros","nextLabel":"Has completado los ocho módulos obligatorios - consulta tu registro completo de evaluaciones"}};
